import com.webcommander.sdk.client.ApiResponse;
import java.util.List;
import java.util.Map;

ApiResponse response = client.taxRules().listTaxRules(Map.of("limit", 20));
Map<?, ?> body = (Map<?, ?>) response.getMap();
for (Object row : (List<?>) body.get("tax_rules")) {
    Map<?, ?> taxRule = (Map<?, ?>) row;
    System.out.println(taxRule.get("id") + " " + taxRule.get("name") + " " + taxRule.get("default"));
}
System.out.println(((Map<?, ?>) body.get("pagination")).get("total"));

